import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s6-u06")
C = "B1-B2"
# Lições de aprofundamento (10–25): vocabulário abstrato.

def X(id, nl, pt, pos="expression"): return V(id, nl, pt, pos)
def N(id, nl, pt, art, pl=None): return V(id, nl, pt, "noun", art, pl)

L(10, "Sufixos -schap e -dom", "Vriendschap, rijkdom.",
  ["Formar e reconhecer substantivos em -schap e -dom"],
  vocab=[N("v-vriendschap","vriendschap","amizade","de","vriendschappen"), N("v-ouderschap","ouderschap","parentalidade","het"),
         N("v-rijkdom","rijkdom","riqueza","de")],
  ex=[("Echte vriendschap is goud waard.","A verdadeira amizade vale ouro."),("Ouderschap is een fulltime baan.","Ser pai/mãe é um trabalho a tempo inteiro."),("Rijkdom maakt niet altijd gelukkig.","A riqueza nem sempre traz felicidade.")],
  review=["v-geluk"],
  gram=[G("g-schap-dom","-schap e -dom","**-schap** forma nomes de relações ou estados: *vriend → vriendschap*, *lid → lidmaatschap*, *wetenschap*. A maioria é **de**, mas alguns são **het** (*het ouderschap*, *het lidmaatschap*, *het landschap*). **-dom** forma estados: *rijk → rijkdom*, *ziek → ziekte* (atenção: não *ziekdom*), *eigendom*, *de ouderdom* (velhice).",
    [("het lidmaatschap","a adesão (ser sócio)"),("de ouderdom","a velhice")])],
  cefr=C, exs=[
    MA([("vriendschap","amizade"),("ouderschap","parentalidade"),("rijkdom","riqueza"),("geluk","felicidade")], "Sufixos.", ["v-vriendschap","v-ouderschap","v-rijkdom","v-geluk"]),
    AR("ouderschap", "parentalidade", "het", "Exceção: het ouderschap.", ["v-ouderschap"]),
    AR("vriendschap", "amizade", "de", "-schap: normalmente de.", ["v-vriendschap"]),
    TR("pt-nl","A verdadeira amizade vale ouro.", ["Echte vriendschap is goud waard","Ware vriendschap is goud waard"], "goud waard.", ["v-vriendschap"]),
    TR("pt-nl","A riqueza nem sempre traz felicidade.", ["Rijkdom maakt niet altijd gelukkig","Rijkdom brengt niet altijd geluk"], "rijkdom.", ["v-rijkdom"]),
    MC("Substantivo de «lid» (membro) com -schap:", ["*lidmaatschap","lidschap|Forma irregular.","liddom|Não."], "Forma.", ["v-vriendschap"]),
    FB("Hun ___ begon op de basisschool.", ["vriendschap"], "Amizade.", ["v-vriendschap"], choices=["vriendschap","rijkdom","ouderschap"], tr="A amizade deles começou na escola primária."),
    FE(["Rijkdom","maken","niet","altijd","gelukkig."], 1, "maakt", "Singular: maakt.", ["v-rijkdom"]),
    LI("Gedeeld ouderschap komt steeds vaker voor.", ["Gedeeld ouderschap komt steeds vaker voor"], "A parentalidade partilhada é cada vez mais frequente.", "Uso.", ["v-ouderschap"]),
  ], diff=4, mins=5)

L(11, "Sufixos -te e -de", "De lengte, de breedte, de warmte.",
  ["Formar nomes de medida e qualidade a partir de adjetivos"],
  vocab=[N("v-lengte","lengte","comprimento|altura (pessoa)","de"), N("v-breedte","breedte","largura","de"),
         N("v-diepte","diepte","profundidade","de"), N("v-warmte","warmte","calor","de")],
  ex=[("Wat is de lengte van de kamer?","Qual é o comprimento do quarto?"),("De breedte is drie meter.","A largura é de três metros."),("De diepte van het meer is tien meter.","A profundidade do lago é de dez metros."),("Ik hou van de warmte van de zon.","Adoro o calor do sol.")],
  review=["v-lang"],
  cefr=C, exs=[
    MA([("lengte","comprimento"),("breedte","largura"),("diepte","profundidade"),("warmte","calor")], "Medidas.", ["v-lengte","v-breedte","v-diepte","v-warmte"]),
    MC("Adjetivo «hoog» → substantivo:", ["*hoogte","hoogheid|Outro sentido (título).","hoogdom|Não."], "-te.", ["v-lengte"]),
    MC("Adjetivo «zwak» → substantivo:", ["*zwakte","zwakheid|Também existe, mas zwakte é comum.","zwakschap|Não."], "-te.", ["v-lengte"]),
    TR("pt-nl","Qual é o comprimento do quarto?", ["Wat is de lengte van de kamer","Wat is de lengte van de kamer?"], "lengte.", ["v-lengte"]),
    TR("pt-nl","A largura é de três metros.", ["De breedte is drie meter","De breedte is 3 meter"], "meter no singular.", ["v-breedte"]),
    FB("Ik mis de ___ van de Portugese zomer.", ["warmte"], "Calor.", ["v-warmte"], choices=["warmte","diepte","breedte"], tr="Tenho saudades do calor do verão português."),
    FE(["De","breedte","is","drie","meters."], 4, "meter.", "Com números: meter (singular).", ["v-breedte"]),
    MC("«Hij is 1,80 m lang. Wat is zijn ___?»", ["*lengte","breedte|Não.","diepte|Não."], "Altura de pessoa = lengte.", ["v-lengte"]),
    LI("Op die diepte is het water ijskoud.", ["Op die diepte is het water ijskoud"], "A essa profundidade a água está gelada.", "Uso.", ["v-diepte"]),
  ], diff=3, mins=5)

L(12, "Palavras internacionais em -iteit e -isme", "Realiteit, kwaliteit, individualisme.",
  ["Reconhecer palavras abstratas parecidas com o português"],
  vocab=[N("v-realiteit","realiteit","realidade","de"), N("v-kwaliteit","kwaliteit","qualidade","de","kwaliteiten"),
         N("v-mentaliteit","mentaliteit","mentalidade","de"), N("v-individualisme","individualisme","individualismo","het")],
  ex=[("De realiteit is anders.","A realidade é diferente."),("Kwaliteit heeft een prijs.","A qualidade tem um preço."),("Dat is een typisch Nederlandse mentaliteit.","Essa é uma mentalidade tipicamente neerlandesa."),("Individualisme is niet altijd negatief.","O individualismo nem sempre é negativo.")],
  review=["v-waarde"],
  gram=[G("g-iteit-isme","-iteit e -isme","Muitas palavras abstratas são internacionais: **-iteit** = *-idade* (*realiteit, kwaliteit, mentaliteit, universiteit*) e são sempre **de**. **-isme** = *-ismo* (*toerisme, individualisme, optimisme*) e são **het**.",
    [("de universiteit","a universidade"),("het optimisme","o otimismo")])],
  cefr=C, exs=[
    MA([("realiteit","realidade"),("kwaliteit","qualidade"),("mentaliteit","mentalidade"),("individualisme","individualismo")], "Internacionais.", ["v-realiteit","v-kwaliteit","v-mentaliteit","v-individualisme"]),
    AR("individualisme", "individualismo", "het", "-isme → het.", ["v-individualisme"]),
    AR("mentaliteit", "mentalidade", "de", "-iteit → de.", ["v-mentaliteit"]),
    AR("toerisme", "turismo", "het", "-isme → het.", ["v-individualisme"]),
    TR("pt-nl","A qualidade tem um preço.", ["Kwaliteit heeft een prijs","Kwaliteit heeft zijn prijs"], "kwaliteit.", ["v-kwaliteit"]),
    TR("pt-nl","A realidade é diferente.", ["De realiteit is anders","De werkelijkheid is anders"], "realiteit / werkelijkheid.", ["v-realiteit"]),
    FB("Hij heeft een echte ondernemers___.", ["mentaliteit"], "Composto.", ["v-mentaliteit"], choices=["mentaliteit","kwaliteit","realiteit"], tr="Ele tem uma verdadeira mentalidade de empreendedor."),
    FE(["Het","kwaliteit","is","uitstekend."], 0, "De", "-iteit → de.", ["v-kwaliteit"]),
    LI("Het optimisme van de jaren negentig is verdwenen.", ["Het optimisme van de jaren negentig is verdwenen","Het optimisme van de jaren 90 is verdwenen"], "O otimismo dos anos noventa desapareceu.", "het optimisme.", ["v-individualisme"]),
  ], diff=3, mins=5)

